        for (int i = 0; i < n; i++) {
            art[i].draw();
            totalArea += art[i].area();
        }
        System.out.printf("Total area: %.2f%n", totalArea);
    }
}

interface Drawable {
    void draw();

    double area();
}

abstract class Shape {
    String name;

    Shape(String name) {
        this.name = name;
    }

    abstract double area();
}

class Circle extends Shape implements Drawable {
    double r;

    Circle(double r) {
        super("circle");
        this.r = r;
    }

    public double area() {
        return Math.PI * r * r;
    }

    public void draw() {
        System.out.println("Render " + name + " area " + String.format("%.2f", area()));
    }
}

class Square extends Shape implements Drawable {
    double s;

    Square(double s) {
        super("square");
        this.s = s;
    }

    public double area() {
        return s * s;
    }

    public void draw() {
        System.out.println("Render " + name + " area " + String.format("%.2f", area()));
    }
}
